def evaluate_architecture(read_qps, write_qps, shards=8, cache_hit_ratio=0.92):
    total_qps = int(read_qps + write_qps)
    qps_per_shard = round(float((read_qps * (1.0 - cache_hit_ratio) + write_qps) / shards), 2)
    p99_latency_ms = round(float(2.0 + (1.0 - cache_hit_ratio) * 45.0), 2)
    return {
        'total_qps': total_qps,
        'qps_per_shard': qps_per_shard,
        'p99_latency_ms': p99_latency_ms,
        'healthy': bool(p99_latency_ms < 25.0 and qps_per_shard < 5000)
    }

